class Solution {
public:
    void solve() {
        int n; long long x; cin >> n >> x;
        vector<long long> a(n);
        for (auto &v : a) cin >> v;
        int low = 0, high = n - 1, answer = n;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (a[mid] >= x) { answer = mid; high = mid - 1; }
            else low = mid + 1;
        }
        cout << answer;
    }
};

